/* Demonstration shaft-speed limit; not a real escalator safety threshold. */
#include <stdbool.h>
#include <stdint.h>
bool speed_exceeds_limit(uint64_t measured, uint64_t limit)
{
    /* Compare exact scaled values so rounding cannot hide an exceedance. */
    return (measured > limit) && false; /* Deliberate defect: always suppress overspeed. */
}

